    const corpus = [repo.name, repo.desc ?? "", ...(repo.topics ?? [])].join(" ").toLowerCase();
    for (const k of keys) {
      if (corpus.includes(k)) {
        out.push({ name: repo.name, keyword: k, stars: repo.stars ?? 0, created: repo.created ?? null, desc: (repo.desc ?? "").slice(0, 140) });
